const body = $json.body ?? $json;
const slug = (body.project_slug ?? '').toString().trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
if (!slug) throw new Error('project_slug is required in the JSON body.');
const regenRaw = (body.regen_ids ?? '').toString();
const regenIds = regenRaw.split(/[,\s]+/).map((x) => x.trim().toLowerCase()).filter(Boolean);
const imageModel = (body.image_model ?? '').toString().trim() || 'google/gemini-3.1-flash-image';
return [{ json: { slug, regen_ids: regenIds, image_model: imageModel } }];

const shot = $json.item ?? $json;
const lines = ['Cinematic 16:9 film still, single frame.'];
if (shot.style_notes) lines.push('Overall style: ' + shot.style_notes);
for (const c of (shot.character_blocks ?? [])) {
  lines.push(c.name + ': ' + c.visual_description + ' Use the attached reference image(s) of ' + c.name + ' and keep facial features, hairstyle, body type, and clothing exactly consistent.');
}
lines.push('Scene: ' + shot.image_prompt);
lines.push('Photorealistic, cinematic lighting. No text, captions, watermarks, or borders.');
return { json: { shotId: shot.id, slug: shot.slug, image_model: shot.image_model ?? 'google/gemini-3.1-flash-image', prompt: lines.join('\n') } };

const srcs = $('Build Image Request').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json ?? {};
  const src = srcs[i] ? srcs[i].json : {};
  const shotId = src.shotId ?? ('unknown_' + i);
  const slug = src.slug;
  const arr = Array.isArray(resp.data) ? resp.data : [];
  const img = arr.find((d) => d && d.b64_json);
  if (!img) {
    const reason = (resp.error && (resp.error.message || resp.error.code))
      || (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content)
      || 'no image in OpenRouter response';
    throw new Error('Shot ' + shotId + ' failed: ' + String(reason).slice(0, 300));
  }
  out.push({ json: { slug, shotId, imageB64: img.b64_json } });
}
return out;
